pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: proxyContract (address used to deploy a proxy that will call setOwner) and target (the desired new owner)
    // We fuzz both the proxy's deployer and the target owner address indirectly by deploying the proxy from a fuzzed creator.
    function testFuzz_property(address deployer, address target) public {
        // Keep domain wide but avoid zero addresses for deployer because vm.prank with address(0) is ambiguous
        vm.assume(deployer != address(0));
        // target can be zero; allow it — the reference contract permits setting owner to address(0)

        // Deploy a minimal proxy contract from `deployer` that will call c.setOwner(target)
        vm.prank(deployer);
        CallerProxy proxy = new CallerProxy(c);

        // Make sure the proxy calls setOwner with its own msg.sender == proxy and tx.origin == deployer
        // Call as deployer (so tx.origin == deployer) but msg.sender for c will be proxy
        vm.prank(deployer);
        proxy.callSetOwner(target);

        // General rule (the single assertion): after a successful proxied call, the reference contract's owner() equals the provided target.
        // This holds for the reference C for all admissible inputs. The mutant that assigns owner = tx.origin will set owner to `deployer` instead when proxied,
        // causing this assertion to fail for some inputs (when deployer != target).
        assertTrue(c.owner() == target);
    }
}

// Minimal helper contract that calls C.setOwner on behalf of its deployer
contract CallerProxy {
    C immutable c;
    constructor(C _c) {
        c = _c;
    }
    function callSetOwner(address _owner) external {
        // msg.sender seen by C will be this contract; tx.origin will be original EOA (the deployer/prank caller)
        c.setOwner(_owner);
    }
}

