pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: proxy (a contract through which the owner will call), target newOwner
    function testFuzz_property(address proxyAddr, address newOwner) public {
        // keep inputs sensible: proxyAddr must be non-zero and not equal to address(this) to allow deployment
        vm.assume(proxyAddr != address(0));
        vm.assume(newOwner != address(0));
        // Deploy a minimal proxy that will call c.setOwner(newOwner) when instructed
        // We want a contract whose address is not an EOA from fuzzer; to allow varied addresses we ignore proxyAddr as exact deploy slot
        ProxyCaller proxy = new ProxyCaller();

        // Arrange: current owner is address(this) because setUp deployed c from this contract
        // Now have the current owner (this) instruct the proxy to call c.setOwner(newOwner)
        // But msg.sender in c will be the proxy, while tx.origin remains this test contract's EOA

        // Make the proxy perform the call as if the owner (this) triggered it
        // We call proxy.callSetOwner which performs c.setOwner(newOwner)
        proxy.callSetOwner(address(c), newOwner);

        // The correct contract should set owner == newOwner (because msg.sender is proxy but owner param is used)
        // The mutant that assigns owner = tx.origin would set owner == tx.origin (which here is this contract's EOA)
        // Assert the universal property: owner equals the provided newOwner
        assertTrue(c.owner() == newOwner);
    }
}

// minimal helper proxy: calls into C on behalf of its caller
contract ProxyCaller {
    function callSetOwner(address caddr, address newOwner) public {
        C(caddr).setOwner(newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor is the caller who must be current owner, newOwner is the address to set
    function testFuzz_property(address actor, address newOwner) public {
        // Keep domain wide but ensure actor is not zero to avoid confusing semantics
        vm.assume(actor != address(0));

        // Make sure the contract's initial owner is the deployer (this) per constructor.
        // Now we want to simulate the current owner calling setOwner; we will first transfer ownership
        // to the fuzzed actor by having the current owner (this test contract) call setOwner(actor).
        bool ok;
        // current owner is address(this) (the test contract) because setUp deployed c
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        // If the above revert'd, the precondition (we must be owner) failed; skip such cases
        vm.assume(ok);

        // Now actor (the new owner) calls setOwner(newOwner). We capture whether the call completed
        // and we also capture the returned boolean value via low-level call since Solidity try/catch on external
        // calls to non-contracts won't return the boolean; instead we use abi.encodeWithSelector and low-level call.
        bytes memory payload = abi.encodeWithSelector(c.setOwner.selector, newOwner);
        (bool success, bytes memory ret) = vm.ffi(abi.encodePacked());

        // The fuzzer cannot directly perform a call as another EOA using vm.prank and get the return value
        // from a high-level call; but we can use vm.prank and a low-level call on address(c) to get the return data.
        vm.prank(actor);
        (bool succ, bytes memory returndata) = address(c).call(payload);

        // If the call reverted, succ == false. If it succeeded, returndata should be the ABI-encoded bool.
        // The universal property: when the caller is the owner, the call should succeed and return true.
        // So for the reference implementation succ==true and abi.decode(returndata, (bool))==true for all inputs.
        // The mutant will sometimes return false while still succeeding.

        // We assert the property by requiring the call succeeded and returned true.
        if (succ) {
            bool returned = abi.decode(returndata, (bool));
            assertTrue(returned);
        } else {
            // If call reverted, fail the test (reference should not revert when called by owner)
            assertTrue(false);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the new owner and also fuzz an address that will act as the caller (must be the current owner)
    function testFuzz_property(address newOwner, address caller) public {
        // keep caller non-zero and newOwner arbitrary
        vm.assume(caller != address(0));

        // make the fuzzer-chosen caller the owner by deploying c in setUp() (owner == address(this))
        // we need to transfer ownership to caller first so that caller is the owner when invoking setOwner
        // do this by having the current owner (this contract) call setOwner(caller)
        bool ok;
        // this contract is the current owner (deployed c in setUp)
        try c.setOwner(caller) returns (bool ret) { ok = ret; } catch { ok = false; }
        // it must succeed on the reference implementation; assume it did so we can proceed testing caller's invocation
        vm.assume(ok);

        // now have the fuzzed caller invoke setOwner(newOwner)
        vm.prank(caller);
        bool ok2;
        try c.setOwner(newOwner) returns (bool ret2) { ok2 = ret2; } catch { ok2 = false; }

        // General rule: when the caller is the current owner, setOwner(...) returns true (and updates owner).
        // We assert the return boolean observed from c.setOwner(newOwner) is true. This is a getter of behavior
        assertTrue(ok2);
    }
}
